package local.velo.bridge;
import android.content.Context;import android.graphics.*;import android.view.View;import android.os.SystemClock;import java.util.*;
/** Draws the same 135 x 240 layout from the most recently transmitted board packet. */
public final class BoardPreview extends View {
 final Paint p=new Paint(3);boolean stats;String last="";float speed=-1;double trip;long seconds;char turn='N';int meters=-1,phase=-1,left,span=100,heading,quality;boolean map,gpsWait,replay,off;long sequence;final ArrayList<int[]> route=new ArrayList<>(),roads=new ArrayList<>();
 final int bg=0xff080808,fg=0xffffffff,muted=0xff8c928c,green=0xffa4ff00;
 public BoardPreview(Context c){super(c);setContentDescription("码表画面数据同步预览");setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
 void update(){invalidate();}
 void page(boolean data){stats=data;invalidate();}
 void parse(String packet){speed=-1;trip=0;seconds=0;turn='N';meters=-1;phase=-1;map=false;gpsWait=false;route.clear();roads.clear();for(String line:packet.split("\n")){String[] a=line.split(",");try{if(a[0].equals("D")&&a.length==6){speed=Float.parseFloat(a[1]);trip=Double.parseDouble(a[2]);seconds=Long.parseLong(a[3]);turn=a[4].charAt(0);meters=Integer.parseInt(a[5]);}else if(a[0].equals("H")&&a.length>=12){int n=Integer.parseInt(a[11]);if(n<0||n>40||a.length!=12+n*5)continue;sequence=Long.parseLong(a[1]);replay=a[2].equals("R");off=a[3].equals("1");turn=a[4].charAt(0);meters=Integer.parseInt(a[5]);left=Integer.parseInt(a[6]);span=Integer.parseInt(a[7]);heading=Integer.parseInt(a[8]);quality=Integer.parseInt(a[10]);for(int i=0;i<n;i++){int[] v=new int[5];for(int j=0;j<5;j++)v[j]=Integer.parseInt(a[12+i*5+j]);route.add(v);}map=true;}else if(a[0].equals("B")&&a.length>=3&&Long.parseLong(a[1])==sequence){int n=Integer.parseInt(a[2]);if(n<0||n>150||a.length!=3+n*5)continue;for(int i=0;i<n;i++){int[] v=new int[5];for(int j=0;j<5;j++)v[j]=Integer.parseInt(a[3+i*5+j]);roads.add(v);}}else if(a[0].equals("T")&&a.length==4&&Long.parseLong(a[1])==sequence)phase=Integer.parseInt(a[2]);else if(line.equals("GPSWAIT")||line.equals("MAPOFF")){gpsWait=line.equals("GPSWAIT");map=false;turn='N';meters=-1;}}catch(RuntimeException ignored){}}}
 void text(Canvas c,String s,float x,float y,float size,int color){p.setColor(color);p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.MONOSPACE);p.setTextSize(size);c.drawText(s,x,y,p);}
 void box(Canvas c,float x,float y,float w,float h,int color){p.setColor(color);p.setStyle(Paint.Style.FILL);c.drawRoundRect(x,y,x+w,y+h,4,4,p);}
 String distance(int m){return m<0?"-- m":m>=1000?String.format(Locale.US,"%.1f km",m/1000.):m+" m";}
 String title(){return off?"OFF ROUTE":phase==8?"WRONG WAY":phase==7?"CHECK GPS":phase==9?"GPS FIX OK":phase==10?"STOPPED":turn=='L'?"TURN LEFT":turn=='R'?"TURN RIGHT":turn=='U'?"U TURN":turn=='O'?"ROUNDABOUT":turn=='A'?"ARRIVED":turn=='N'?"CHECK ROUTE":"STRAIGHT";}
 String detail(){return off?"REPLAN":phase==8?"TURN BACK":phase==7?"WAIT GPS":phase==9?"MOVE TO SET":turn=='A'?"FINISH":turn=='N'?"CHECK":distance(meters);}
 void glyph(Canvas c,char t,float x,float y,float size,int color){p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setStrokeJoin(Paint.Join.ROUND);Path path=new Path();if(t=='L'||t=='R'){int d=t=='L'?-1:1;path.moveTo(x,y+size/2);path.lineTo(x,y-size/3);path.lineTo(x+d*size/2,y-size/3);path.moveTo(x+d*size/4,y-size*2/3);path.lineTo(x+d*size/2,y-size/3);path.lineTo(x+d*size/4,y);}else if(t=='O'){c.drawCircle(x,y,size/2,p);}else if(t=='U'){path.moveTo(x+size/3,y+size/2);path.lineTo(x+size/3,y-size/3);path.quadTo(x,y-size,x-size/3,y-size/3);path.lineTo(x-size/3,y+size/2);path.lineTo(x-size/2,y+size/5);}else if(t=='N'){text(c,"?",x-5,y+6,size,color);}else if(t=='A'){c.drawCircle(x,y,size/2,p);}else{path.moveTo(x,y+size/2);path.lineTo(x,y-size/2);path.moveTo(x-size/3,y-size/6);path.lineTo(x,y-size/2);path.lineTo(x+size/3,y-size/6);}c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}
 void lines(Canvas c,ArrayList<int[]> segments,boolean planned){for(int[] a:segments){p.setColor(planned?(a[4]==1?green:0xff647078):a[4]==2?0xff6a8380:0xff3c6069);p.setStrokeWidth(planned?3:a[4]==2?2:1);c.drawLine(4+a[0],54+a[1],4+a[2],54+a[3],p);}}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float scale=Math.min(getWidth()/135f,getHeight()/240f);c.save();c.translate((getWidth()-135*scale)/2,(getHeight()-240*scale)/2);c.scale(scale,scale);c.drawColor(bg);String packet=DeviceLinkService.lastSent;boolean fresh=RideService.connected&&packet!=null&&SystemClock.elapsedRealtime()-DeviceLinkService.sentAt<5000;if(!fresh){text(c,"VELO",7,14,8,green);text(c,RideService.connected?"WAITING FOR":"DISCONNECTED",9,110,11,fg);text(c,RideService.connected?"BOARD DATA":"RECONNECTING",9,128,10,muted);c.restore();return;}if(!packet.equals(last)){parse(packet);last=packet;}text(c,"VELO",7,12,8,green);
 if(map&&!stats){text(c,replay?"REPLAY":phase==9?"GPS FIX":phase==10?"STOP":"GPS",87,12,7,muted);text(c,speed>=0?String.format(Locale.US,"%.1f",speed):"--.-",5,46,25,fg);text(c,"km/h",104,44,7,muted);box(c,4,54,128,128,0xff101820);c.save();c.clipRect(4,54,132,182);lines(c,roads,false);lines(c,route,true);if(roads.isEmpty())text(c,"ROUTE ONLY",9,66,7,muted);p.setColor(bg);c.drawCircle(68,146,10,p);p.setColor(fg);c.drawCircle(68,146,9,p);if(phase==9||(phase==7&&quality==0)){p.setColor(0xffffb340);c.drawCircle(68,146,4,p);}else glyph(c,'S',68,146,12,0xff48ddff);text(c,"N",116,69,8,fg);text(c,distance(Math.max(10,span/4)),10,173,7,fg);c.restore();box(c,4,187,128,39,phase==8?0xffc03035:off||phase==7?0xff924000:0xff182428);glyph(c,off||phase==7||phase==8||phase==9?'N':turn,22,207,18,fg);text(c,title(),42,200,7,fg);text(c,detail(),42,219,9,fg);text(c,distance(left)+" LEFT",5,239,7,muted);text(c,roads.isEmpty()?"GPS":"OSM",111,239,7,muted);
 }else if(gpsWait&&!stats){text(c,"GPS WAIT",7,69,19,0xffffb340);text(c,"LOCATION LOST",7,100,9,fg);text(c,"NO OLD DIRECTIONS",7,119,7,muted);text(c,"PHONE GPS REQUIRED",7,237,7,muted);
 }else{text(c,"LIVE",67,14,8,muted);p.setColor(0xff29454a);c.drawLine(7,23,128,23,p);String v=speed>=0?String.format(Locale.US,"%.1f",speed):"--.-";text(c,v,(135-v.length()*17)/2f,65,28,fg);text(c,"km/h",53,82,8,muted);c.drawLine(7,92,128,92,p);text(c,"TRIP km",8,110,7,muted);text(c,"TIME",76,110,7,muted);text(c,String.format(Locale.US,"%.2f",trip),8,125,8,fg);text(c,String.format(Locale.US,"%02d:%02d:%02d",seconds/3600,seconds/60%60,seconds%60),76,125,7,fg);if(map&&phase>=6&&phase<=9){text(c,title(),8,158,9,fg);text(c,detail(),8,178,8,muted);}else if(gpsWait){text(c,"WAITING FOR GPS",8,162,8,0xffffb340);text(c,"TRIP DATA KEPT",8,183,8,muted);}else if(turn=='N'){text(c,"NO TURN DATA",19,162,8,muted);text(c,"CHECK PHONE",19,183,8,muted);}else{glyph(c,turn,67,158,36,green);text(c,distance(meters),37,205,13,green);text(c,title(),18,222,8,fg);}text(c,"PHONE CONNECTED",7,238,7,muted);}c.restore();
 }
}
